"use client";

import { XIcon } from "lucide-react";
import type { ComponentProps, CSSProperties, MouseEvent, ReactNode } from "react";
import { createContext, useContext, useLayoutEffect, useState } from "react";

import type { ButtonKnobStyle } from "@/components/control-ui/knob-contracts/button-knobs";
import type { ChatComposerAttachmentKnobStyle } from "@/components/control-ui/knob-contracts/chat-composer-attachment-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Button } from "@/components/control-ui/ui/button";
import { ScrollArea } from "@/components/control-ui/ui/scroll-area";
import { Spinner } from "@/components/control-ui/ui/spinner";

export type ChatComposerAttachmentKind = "image" | "pdf" | "spreadsheet" | "document" | "archive" | "audio" | "video" | "file";
export type ChatComposerAttachmentStatus = "idle" | "uploading" | "uploaded" | "error";
export type ChatComposerAttachmentVariant = "auto" | "preview" | "file";

type ChatComposerAttachmentContextValue = {
  name: string;
  type?: string;
  description?: ReactNode;
  status: ChatComposerAttachmentStatus;
  progress?: number;
  previewUrl?: string;
  kind: ChatComposerAttachmentKind;
  variant: Exclude<ChatComposerAttachmentVariant, "auto">;
  extension: string;
  onRemove?: () => void;
  removeLabel?: string;
};

const ChatComposerAttachmentContext = createContext<ChatComposerAttachmentContextValue | null>(null);

function useChatComposerAttachmentContext() {
  const context = useContext(ChatComposerAttachmentContext);
  if (!context) throw new Error("ChatComposerAttachment compound components must be rendered inside <ChatComposerAttachment>.");
  return context;
}

function extensionFromName(name: string) {
  const match = name.match(/\.([a-z0-9]+)$/i);
  return match?.[1]?.toLowerCase() ?? "";
}

function kindFromAttachment(type: string | undefined, name: string): ChatComposerAttachmentKind {
  const mime = type?.toLowerCase() ?? "";
  const extension = extensionFromName(name);

  if (mime.startsWith("image/") || ["avif", "gif", "heic", "jpeg", "jpg", "png", "webp"].includes(extension)) return "image";
  if (mime === "application/pdf" || extension === "pdf") return "pdf";
  if (
    mime.includes("spreadsheet") ||
    mime.includes("excel") ||
    mime.includes("csv") ||
    ["csv", "numbers", "ods", "tsv", "xls", "xlsx"].includes(extension)
  ) {
    return "spreadsheet";
  }
  if (mime.startsWith("audio/") || ["aac", "flac", "m4a", "mp3", "ogg", "wav"].includes(extension)) return "audio";
  if (mime.startsWith("video/") || ["avi", "mov", "mp4", "webm"].includes(extension)) return "video";
  if (mime.includes("zip") || ["7z", "gz", "rar", "tar", "zip"].includes(extension)) return "archive";
  if (mime.includes("document") || mime.includes("text") || ["doc", "docx", "md", "rtf", "txt"].includes(extension)) return "document";
  return "file";
}

function resolveVariant(
  variant: ChatComposerAttachmentVariant,
  kind: ChatComposerAttachmentKind,
  status: ChatComposerAttachmentStatus,
  previewUrl: string | undefined,
): Exclude<ChatComposerAttachmentVariant, "auto"> {
  if (variant !== "auto") return variant;
  if (status === "error") return "file";
  return previewUrl || kind === "image" ? "preview" : "file";
}

function useObjectUrl(blob: Blob | undefined) {
  const [objectUrl, setObjectUrl] = useState<{ blob: Blob; url: string }>();

  useLayoutEffect(() => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    setObjectUrl({ blob, url });
    return () => URL.revokeObjectURL(url);
  }, [blob]);

  return blob && objectUrl?.blob === blob ? objectUrl.url : undefined;
}

function progressValue(progress: number | undefined) {
  if (typeof progress !== "number" || Number.isNaN(progress)) return undefined;
  return Math.min(100, Math.max(0, progress));
}

function fallbackLabel(kind: ChatComposerAttachmentKind, extension: string) {
  if (extension && extension.length <= 4) return extension.toUpperCase();
  const labels: Record<ChatComposerAttachmentKind, string> = {
    image: "IMG",
    pdf: "PDF",
    spreadsheet: "XLS",
    document: "DOC",
    archive: "ZIP",
    audio: "AUD",
    video: "VID",
    file: "FILE",
  };
  return labels[kind];
}

function defaultDescription(context: ChatComposerAttachmentContextValue) {
  const { progress } = context;
  if (context.description) return context.description;
  if (context.status === "uploading") return progress === undefined ? "Uploading…" : `Uploading ${Math.round(progress)}%`;
  if (context.status === "error") return "Upload failed";
  return fallbackLabel(context.kind, context.extension);
}

export type ChatComposerAttachmentsProps = ComponentProps<"div"> & {
  label?: string;
  viewportClassName?: string;
} & { style?: CSSProperties & ChatComposerAttachmentKnobStyle };

export function ChatComposerAttachments({
  label = "Attachments",
  className,
  viewportClassName,
  children,
  ...props
}: ChatComposerAttachmentsProps) {
  return (
    <div
      data-control-ui="chat-composer-attachments"
      data-control-family="chat-composer-attachment"
      data-slot="root"
      className={cn("min-w-0", className)}
      {...props}
    >
      <ScrollArea
        data-control-ui="chat-composer-attachments"
        data-slot="scroll"
        aria-label={label}
        lockAxis="y"
        mask
        scrollbarVisibility="hover"
        className="w-full"
        viewportClassName={viewportClassName}
      >
        <ul
          data-control-ui="chat-composer-attachments"
          data-control-family="chat-composer-attachment"
          data-slot="list"
          className="flex w-max min-w-full list-none"
        >
          {children}
        </ul>
      </ScrollArea>
    </div>
  );
}

type ChatComposerAttachmentSource = { file: File; name?: string } | { file?: undefined; name: string };

export type ChatComposerAttachmentProps = Omit<ComponentProps<"li">, "style"> &
  ChatComposerAttachmentSource & {
    type?: string;
    description?: ReactNode;
    status?: ChatComposerAttachmentStatus;
    progress?: number;
    previewUrl?: string;
    kind?: ChatComposerAttachmentKind;
    variant?: ChatComposerAttachmentVariant;
    onRemove?: () => void;
    removeLabel?: string;
    style?: CSSProperties & ChatComposerAttachmentKnobStyle;
  };

export function ChatComposerAttachment({
  file,
  name: nameInput,
  type: typeInput,
  description,
  status = "idle",
  progress: progressInput,
  previewUrl: previewUrlInput,
  kind,
  variant = "auto",
  onRemove,
  removeLabel,
  className,
  children,
  "aria-label": ariaLabel,
  ...props
}: ChatComposerAttachmentProps) {
  const name = nameInput ?? file?.name ?? "";
  const type = typeInput ?? file?.type;
  const resolvedKind = kind ?? kindFromAttachment(type, name);
  const resolvedVariant = resolveVariant(variant, resolvedKind, status, previewUrlInput);
  const filePreviewUrl = useObjectUrl(resolvedVariant === "preview" && !previewUrlInput ? file : undefined);
  const previewUrl = previewUrlInput ?? filePreviewUrl;
  const extension = extensionFromName(name);
  const progress = progressValue(progressInput);

  return (
    <ChatComposerAttachmentContext.Provider
      value={{
        name,
        type,
        description,
        status,
        progress,
        previewUrl,
        kind: resolvedKind,
        variant: resolvedVariant,
        extension,
        onRemove,
        removeLabel,
      }}
    >
      <li
        aria-label={ariaLabel ?? name}
        data-control-ui="chat-composer-attachment"
        data-control-family="chat-composer-attachment"
        data-slot="root"
        data-surface="panel"
        data-kind={resolvedKind}
        data-state={status}
        data-variant={resolvedVariant}
        className={cn("relative isolate flex shrink-0 items-center overflow-hidden", className)}
        {...props}
      >
        {children ?? (
          <>
            <ChatComposerAttachmentPreview />
            {resolvedVariant === "file" && (
              <ChatComposerAttachmentContent>
                <ChatComposerAttachmentTitle />
                <ChatComposerAttachmentDescription />
              </ChatComposerAttachmentContent>
            )}
            <ChatComposerAttachmentRemove />
            <ChatComposerAttachmentProgress />
          </>
        )}
      </li>
    </ChatComposerAttachmentContext.Provider>
  );
}

export type ChatComposerAttachmentPreviewProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatComposerAttachmentKnobStyle;
};

export function ChatComposerAttachmentPreview({ className, children, ...props }: ChatComposerAttachmentPreviewProps) {
  const context = useChatComposerAttachmentContext();
  const label = fallbackLabel(context.kind, context.extension);

  return (
    <div
      data-control-ui="chat-composer-attachment"
      data-control-family="chat-composer-attachment"
      data-slot="preview"
      className={cn("relative flex shrink-0 items-center justify-center overflow-hidden", className)}
      {...props}
    >
      {children ??
        (context.previewUrl ? (
          <img
            src={context.previewUrl}
            alt={context.name}
            loading="lazy"
            decoding="async"
            className="h-full w-auto max-w-full object-contain"
          />
        ) : (
          <span
            data-control-ui="chat-composer-attachment"
            data-control-family="chat-composer-attachment"
            data-slot="preview-label"
            className="uppercase"
          >
            {label}
          </span>
        ))}
    </div>
  );
}

export type ChatComposerAttachmentContentProps = ComponentProps<"div"> & { style?: CSSProperties & ChatComposerAttachmentKnobStyle };

export function ChatComposerAttachmentContent({ className, ...props }: ChatComposerAttachmentContentProps) {
  return (
    <div
      data-control-ui="chat-composer-attachment"
      data-control-family="chat-composer-attachment"
      data-slot="content"
      className={cn("min-w-0 flex-1", className)}
      {...props}
    />
  );
}

export type ChatComposerAttachmentTitleProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatComposerAttachmentKnobStyle;
};

export function ChatComposerAttachmentTitle({ className, children, ...props }: ChatComposerAttachmentTitleProps) {
  const { name } = useChatComposerAttachmentContext();

  return (
    <div
      data-control-ui="chat-composer-attachment"
      data-control-family="chat-composer-attachment"
      data-slot="title"
      className={cn("truncate", className)}
      {...props}
    >
      {children ?? name}
    </div>
  );
}

export type ChatComposerAttachmentDescriptionProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatComposerAttachmentKnobStyle;
};

export function ChatComposerAttachmentDescription({ className, children, ...props }: ChatComposerAttachmentDescriptionProps) {
  const context = useChatComposerAttachmentContext();

  return (
    <div
      data-control-ui="chat-composer-attachment"
      data-control-family="chat-composer-attachment"
      data-slot="description"
      className={cn("truncate", className)}
      data-state={context.status}
      {...props}
    >
      {children ?? defaultDescription(context)}
    </div>
  );
}

export type ChatComposerAttachmentRemoveProps = Omit<ComponentProps<typeof Button>, "style"> & {
  style?: CSSProperties & ButtonKnobStyle & ChatComposerAttachmentKnobStyle;
};

export function ChatComposerAttachmentRemove({
  className,
  onClick,
  children,
  "aria-label": ariaLabel,
  ...props
}: ChatComposerAttachmentRemoveProps) {
  const { name, onRemove, removeLabel } = useChatComposerAttachmentContext();

  if (!onRemove) return null;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (!event.defaultPrevented) onRemove?.();
  }

  return (
    <Button
      data-control-ui="chat-composer-attachment"
      data-chat-composer-attachment-remove="true"
      iconOnly
      data-slot="remove"
      aria-label={ariaLabel ?? removeLabel ?? `Remove ${name}`}
      size="xs"
      variant="solid"
      className={cn("absolute right-1 top-1 z-10", className)}
      onClick={handleClick}
      {...props}
    >
      {children ?? <XIcon aria-hidden="true" className="size-3" />}
    </Button>
  );
}

export type ChatComposerAttachmentProgressProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatComposerAttachmentKnobStyle;
};

export function ChatComposerAttachmentProgress({ className, children, ...props }: ChatComposerAttachmentProgressProps) {
  const { name, status, progress } = useChatComposerAttachmentContext();

  if (status !== "uploading") return null;

  return (
    <div
      role="progressbar"
      aria-label={`Uploading ${name}`}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={progress}
      data-control-ui="chat-composer-attachment"
      data-control-family="chat-composer-attachment"
      data-slot="progress"
      className={cn("pointer-events-none absolute inset-0 z-1 grid place-items-center", className)}
      {...props}
    >
      {children ?? (
        <>
          <div
            data-control-ui="chat-composer-attachment"
            data-control-family="chat-composer-attachment"
            data-slot="progress-indicator"
            className="absolute inset-y-0 end-0"
            style={{ inlineSize: `${100 - (progress ?? 0)}%` }}
          />
          {progress === undefined && <Spinner aria-hidden="true" className="relative" size="xs" />}
        </>
      )}
    </div>
  );
}

@layer components {
  :where([data-control-family="chat-composer-attachment"][data-slot="root"]:not([data-variant])) {
    --cui-chat-composer-attachment-list-padding: calc(var(--spacing) * 3);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant]) {
    --cui-chat-composer-attachment-background: var(--popover);
    --cui-chat-composer-attachment-border-color: var(--control-rim);
    --cui-chat-composer-attachment-height: calc(var(--spacing) * 14);
    --cui-chat-composer-attachment-radius: var(--radius-popover);
    --cui-chat-composer-attachment-image-outline-color: oklch(from var(--foreground) l c h / 0.1);
    --cui-chat-composer-attachment-shadow:
      inset 0 0 0 var(--control-rim-width) var(--cui-chat-composer-attachment-border-color), var(--shadow-sm);
    --cui-chat-composer-attachment-backdrop-filter: blur(var(--backdrop-blur-popover));
    --cui-chat-composer-attachment-progress-background: transparent;
    --cui-chat-composer-attachment-progress-foreground: oklch(from var(--background) l c h / var(--overlay-opacity));
    block-size: var(--cui-chat-composer-attachment-height);
    text-align: left;
    border-radius: var(--cui-chat-composer-attachment-radius);
    background: var(--cui-chat-composer-attachment-background);
    box-shadow: var(--cui-chat-composer-attachment-shadow);
    backdrop-filter: var(--cui-chat-composer-attachment-backdrop-filter);
    transition-property: background-color, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="list"]) {
    gap: calc(var(--spacing) * 2);
    padding: var(--cui-chat-composer-attachment-list-padding);
  }

  :where(
    [data-control-family="chat-composer"][data-slot="shell"]
      [data-control-family="chat-composer-attachment"][data-slot="root"][data-variant]
  ) {
    --cui-chat-composer-attachment-radius: max(
      var(--radius-sm),
      min(
        calc(var(--cui-chat-composer-attachment-height) / 2),
        calc(var(--cui-chat-composer-shell-radius) - var(--cui-chat-composer-attachment-list-padding))
      )
    );
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant="preview"]) {
    inline-size: fit-content;
    max-inline-size: calc(var(--spacing) * 40);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant="file"]) {
    inline-size: calc(var(--spacing) * 64);
    max-inline-size: calc(100vw - 5rem);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant="preview"] [data-slot="preview"]) {
    block-size: 100%;
    inline-size: fit-content;
    min-inline-size: calc(var(--spacing) * 10);
    max-inline-size: 100%;
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="content"]) {
    padding-inline: calc(var(--spacing) * 3) calc(var(--spacing) * 8);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-state="error"]) {
    --cui-chat-composer-attachment-border-color: oklch(from var(--destructive) l c h / 0.45);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="preview"]) {
    background: var(--muted);
    color: var(--muted-foreground);
    border-radius: inherit;
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="preview"] > img) {
    border-radius: inherit;
    outline: 1px solid var(--cui-chat-composer-attachment-image-outline-color);
    outline-offset: -1px;
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant="file"] [data-slot="preview"]) {
    inline-size: calc(var(--spacing) * 14);
    block-size: 100%;
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  :where([data-control-family="chat-composer-attachment"][data-kind="pdf"] [data-slot="preview"]) {
    background: oklch(from var(--destructive) l c h / 0.1);
    color: var(--destructive-text);
  }

  :where([data-control-family="chat-composer-attachment"][data-kind="spreadsheet"] [data-slot="preview"]) {
    background: oklch(from var(--primary) l c h / 0.1);
    color: var(--primary-text);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="preview-label"]) {
    font-size: var(--text-micro);
    font-weight: var(--font-weight-semibold);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="title"]) {
    color: var(--popover-foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="description"][data-state="error"]) {
    color: var(--destructive-text);
  }

  :where([data-control-family="button"][data-chat-composer-attachment-remove="true"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
    padding: 0;
    --cui-button-radius: 9999px;
    --cui-button-background: var(--foreground);
    --cui-button-foreground: var(--background);
    --cui-button-shadow: var(--shadow-sm);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-chat-composer-attachment-remove="true"]:hover) {
      --cui-button-hover-background: oklch(from var(--foreground) l c h / 0.85);
      --cui-button-hover-foreground: var(--background);
    }
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="progress"]) {
    background: var(--cui-chat-composer-attachment-progress-background);
  }

  :where([data-control-family="chat-composer-attachment"][data-slot="progress-indicator"]) {
    background: var(--cui-chat-composer-attachment-progress-foreground);
    transition-property: inline-size;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-standard);
  }
}

@property --cui-chat-composer-attachment-radius {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-composer-attachment-height {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-composer-attachment-list-padding {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-composer-attachment-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-composer-attachment-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-composer-attachment-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-chat-composer-attachment-backdrop-filter {
  syntax: "*";
  inherits: true;
}

@property --cui-chat-composer-attachment-progress-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-composer-attachment-progress-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-composer-attachment-image-outline-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}
